export const flow = (labels, caption='Conceptual computation', progressive=false) => `<svg class="flow" viewBox="0 0 1120 180" role="img" aria-label="${caption}"><title>${caption}</title>${labels.map((label,i)=>`<g ${progressive&&i ? 'class="fragment"' : ''}><rect x="${i*(1120/labels.length)+5}" y="30" width="${1120/labels.length-38}" height="100" rx="14"/><text x="${i*(1120/labels.length)+(1120/labels.length-28)/2}" y="88" text-anchor="middle">${label}</text>${i<labels.length-1?`<path d="M ${i*(1120/labels.length)+1120/labels.length-29} 80 h 23 l -7 -6 m 7 6 l -7 6"/>`:''}</g>`).join('')}</svg>`;
export const bars = (labels, values, label='') => `<div class="bars" role="img" aria-label="${label || 'Probabilities'}: ${labels.map((l,i)=>`${l} ${Math.round(values[i]*100)} percent`).join(', ')}">${labels.map((l,i)=>`<div class="bar-row"><span>${l}</span><div class="track"><div style="width:${values[i]*100}%"></div></div><strong>${Math.round(values[i]*100)}%</strong></div>`).join('')}${label ? `<small>${label}</small>` : ''}</div>`;
const cards = (...items) => `<div class="cards">${items.map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div>`;
const equation = text => `<div class="equation">${text}</div>`;
export const illustrativeTokens = ['{', '\n  "', 'source', '_of', '_wealth', '": "', 'business', '",', '\n  "', 'confidence', '": "', 'high', '"', '\n}'];
export const slides = [];
function add(id, title, seconds, label, body, notes, source=[], extra={}) { slides.push({id,title,minutes:seconds/60,seconds,label,body,notes,source,...extra}); }
add('start','AI That Decides',45,'01 / THE QUESTION',`<p class="subtitle">Jev, System One Models, and the<br>Architecture of Fast Decisions</p><p class="presenter">Matteo Abis</p><p class="meta">An engineering walkthrough · 40 minutes + 5 minutes discussion<br>Source snapshot: 23 October 2026 · TypeSafe examples pin Jev 1.13.0</p>`,
"I’m Matteo Abis. Today we will look at what changes when software can ask a model for a decision directly, instead of asking for text and interpreting the answer.\n\nWe will start with a transaction, build the basic idea from familiar LLM components, then look at calibration and an open implementation. We will finish with benchmarks and two practical workflows. The question to keep in mind is: where do we need intelligence, and where do we simply need the answer in a useful form?",['intro']);
add('interface','Meet Jev',60,'TYPESAFE / PUBLIC RELEASE · 15 SEPTEMBER 2026 · EARLY ACCESS',`<p class="jev-intro-lead">Give it evidence and typed questions.<br>Get decision probabilities directly.</p><div class="jev-overview"><div class="jev-primitives"><h3>One shared state. Three question types.</h3><dl><div><dt>Choice</dt><dd>Which category?<span>Probabilities over your named options.</span></dd></div><div><dt>Score</dt><dd>Where on a scale?<span>Ordered levels, probabilities and a score.</span></dd></div><div><dt>Noul</dt><dd>Yes or no?<span>A number from 0 to 1: P(yes).</span></dd></div></dl></div><div class="jev-pricing"><h3>API price · USD / 1M tokens</h3><table aria-label="Standard API token prices as of 23 October 2026"><thead><tr><th>Model</th><th>Input</th><th>Output</th></tr></thead><tbody><tr class="jev-price"><td>Jev 1.13</td><td>$0.042</td><td>Free</td></tr><tr><td>GPT-6 Luna</td><td>$0.10</td><td>$0.50</td></tr><tr><td>GPT-6 Sol</td><td>$2.00</td><td>$10.00</td></tr><tr><td>GPT-6 Astra</td><td>$10.00</td><td>$50.00</td></tr></tbody></table><p class="small">23 Oct 2026 · Standard, uncached input; OpenAI short context (≤272K). No regional surcharges.</p></div></div>`,"Jev is TypeSafe’s decision model, publicly released in early access on 15 September 2026. Send it shared evidence and typed questions. It returns probabilities directly.\n\nThe three interfaces are Choice, Score and Noul. We will see examples next. Notice the pricing shape: Jev charges for input tokens and has no output-token charge. The comparison here is a dated API price snapshot, not a cost-per-correct-decision benchmark. Actual workflow cost also depends on prompt length, repeated calls and how many cases need further work.",['pricing','openaiPricing','api','rlcd']);
add('choice','Three Ways to Ask',105,'THE INTERFACE / EXAMPLES',`<div class="jev-examples"><article><h3>Choice</h3><p class="primitive-purpose">Pick a category</p><p class="primitive-question">What is the stated source of funds?</p><blockquote>“Proceeds from my consultancy business.”</blockquote>`+bars(['Employment income','Business proceeds','Inheritance','Gift','Unclear'],[.03,.9,.01,.01,.05])+`</article><article><h3>Score</h3><p class="primitive-purpose">Rate on ordered levels</p><p class="primitive-question">How strongly do the documents support the explanation?</p><blockquote>Invoice matches the amount; payment trail is incomplete.</blockquote>`+bars(['0 · Contradicted','1 · Unsupported','2 · Partially supported','3 · Supported'],[0,.1,.8,.1])+`<p class="primitive-result">Expected score: <strong>2.0 / 3</strong></p></article><article><h3>Noul</h3><p class="primitive-purpose">Judge a proposition</p><p class="primitive-question">Does the passage explicitly identify the client as seller?</p><blockquote>“The seller, Mr Example, transfers ownership to the buyer.”</blockquote><div class="noul-example"><strong>0.97</strong><span>P(yes)</span></div><p class="small">97% probability of “yes”.<br>Your code chooses the threshold.</p></article></div>`,"Choice asks which named category fits. Score asks where something belongs on an ordered scale. Noul asks whether a proposition is true and returns a probability of yes.\n\nIn the middle example, an incomplete payment trail means partially supported; missing evidence is not automatically contradiction. Score preserves the order of the levels, while Choice treats its labels as separate categories.\n\nDo not look only at the expected score. A fifty-fifty split between 0 and 3 has the same mean as a fifty-fifty split between 1 and 2, but tells a very different story. Keep the distribution when uncertainty matters.",['choice','score','noul']);
add('decision-transition','What Changes When the Answer Is a Decision?',15,'FROM THE INTERFACE TO THE COMPUTATION',`<div class="decision-pause"><p class="pause-context">Let’s start with a conventional LLM.</p></div>`,"We have seen the interface. Now let’s understand why it changes the computation.\n\nStart with the familiar approach: give a conventional LLM the evidence, then ask it to return JSON.",[]);
add('mismatch','A Transaction Arrives. Classify It.',75,'A WORKED EXAMPLE',`<div class="intro-example"><div class="evidence-column"><article class="ledger-entry"><div class="document-label">ACCOUNT ACTIVITY · 20 OCT 2026</div><div class="ledger-amount">+ USD 1,000,000.00</div><p>Mr Example <span>←</span> Test Corp</p><div class="ledger-detail">Dividend credit · Ref. DIV-2026-1042</div></article><article class="dividend-statement"><div class="statement-heading"><strong>TEST CORP</strong><span>DIVIDEND STATEMENT</span></div><dl><div><dt>Registered holder</dt><dd>Mr Example</dd></div><div><dt>Dividend entitlement</dt><dd>100,000 shares × USD 10.00</dd></div></dl><p class="statement-total">Net dividend paid: <strong>USD 1,000,000.00</strong></p><p class="statement-text">Paid on 20 October 2026. Deductions: USD 0.00.<br>Payment reference: DIV-2026-1042.</p><div class="statement-signoff">Corporate Secretary · Test Corp</div></article></div><div class="generation-panel"><div class="document-label">CONVENTIONAL LLM</div><h3>Classify the source of wealth.</h3><p class="generation-instruction">Return a category and confidence as JSON.</p><div class="generation-window"><div class="generation-status" role="status" aria-live="polite">Complete</div><pre aria-hidden="true"><code class="token-output">${illustrativeTokens.join('')}</code><span class="typing-cursor" aria-hidden="true">▍</span></pre><span class="sr-only">Illustrative output: source of wealth business, confidence high.</span></div><button type="button" data-replay-generation>Replay generation ↻</button></div></div>`,
"Mr Example receives a million-dollar payment from Test Corp. The supporting statement records one hundred thousand shares and a ten-dollar dividend per share. The amount and payment reference match.\n\nOn the right, watch the LLM produce the JSON one piece at a time. Use Replay if needed. Our software wants a category, but the model also emits braces, field names, quotation marks and a confidence word.\n\n“High” is a generated label. It is not automatically a measured probability of being correct. To see where the time goes, let’s follow the computation inside the model.",[]);
add('llm-architecture','Inside a language model',135,'THE ARCHITECTURE · A MODERN DENSE DECODER',`<svg class="llm-architecture" viewBox="0 0 1150 550" role="img" aria-labelledby="llm-architecture-title llm-architecture-description"><title id="llm-architecture-title">A language model processes the input and feeds the selected token back to generate the next one</title><desc id="llm-architecture-description">Input text is tokenized into IDs, embedded as vectors, processed by repeated decoder blocks, and scored by the vocabulary scoring layer. Softmax gives vocabulary probabilities and sampling selects a token ID. Detokenization displays its text. The selected ID is appended to the sequence and fed directly into embeddings for the next prediction, until a stop token or limit. Each simplified block contains causal attention and feed forward, with residual additions. Queries describe what a token seeks, keys identify what other tokens can match, and values carry their information. Attention matches queries with keys and mixes values from the current and earlier tokens. Feed forward uses learned matrix multiplications with non-linear transformations on each token.</desc><defs><marker id="architecture-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker><marker id="architecture-feedback-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs>
<g class="architecture-node"><rect x="5" y="20" width="135" height="78" rx="8"/><text x="72" y="51" class="architecture-heading">Input text</text><text x="72" y="77">“Classify…”</text></g>
<path class="architecture-arrow" d="M 143 59 H 163"/>
<g class="architecture-node"><rect x="170" y="20" width="140" height="78" rx="8"/><text x="240" y="51" class="architecture-heading">Tokenizer</text><text x="240" y="77">text → token IDs</text></g>
<path class="architecture-arrow" d="M 313 59 H 333"/>
<g class="architecture-node"><rect x="340" y="20" width="155" height="78" rx="8"/><text x="417" y="51" class="architecture-heading">Embeddings</text><text x="417" y="77">IDs → vectors</text></g>
<path class="architecture-arrow" d="M 498 59 H 518"/>
<g class="architecture-node architecture-stack"><rect x="533" y="10" width="240" height="78" rx="8"/><rect x="527" y="15" width="240" height="78" rx="8"/><rect x="521" y="20" width="240" height="78" rx="8"/><text x="641" y="51" class="architecture-heading">Decoder blocks × N</text><text x="641" y="77">update the token vectors</text></g>
<path class="architecture-arrow" d="M 776 59 H 963"/>
<g class="architecture-node"><rect x="970" y="20" width="175" height="78" rx="8"/><text x="1057" y="51" class="architecture-heading">Vocab Score</text><text x="1057" y="77">linear → vocab scores</text></g>
<path class="architecture-arrow" d="M 1057 101 V 161"/>
<g class="architecture-node"><rect x="970" y="170" width="175" height="78" rx="8"/><text x="1057" y="201" class="architecture-heading">Softmax</text><text x="1057" y="227">scores → probabilities</text></g>
<path class="architecture-arrow" d="M 1057 251 V 300"/>
<g class="architecture-node"><rect x="970" y="309" width="175" height="78" rx="8"/><text x="1057" y="340" class="architecture-heading">Sampling</text><text x="1057" y="366">choose a token ID</text></g>
<path class="architecture-arrow" d="M 1057 390 V 439"/>
<g class="architecture-node"><rect x="970" y="448" width="175" height="78" rx="8"/><text x="1057" y="479" class="architecture-heading">Detokenize</text><text x="1057" y="505">token ID → text</text></g>
<path class="architecture-zoom" d="M 641 105 V 128 H 465 V 153"/><text x="473" y="146" class="architecture-zoom-label">look inside one block</text>
<rect class="architecture-block" x="15" y="163" width="915" height="316" rx="12"/>
<text class="architecture-block-label" x="35" y="192">ONE DECODER BLOCK</text><text class="architecture-residual-label" x="905" y="192">original vector + add update</text>
<path class="architecture-arrow" d="M 25 322 H 63"/>
<g class="architecture-node architecture-operation"><rect x="70" y="238" width="335" height="185" rx="8"/><text x="237" y="267" class="architecture-heading">Causal attention</text><text x="237" y="297">Q (query) · what this token seeks</text><text x="237" y="323">K (key) · what each token can match</text><text x="237" y="349">V (value) · information it can share</text><text x="237" y="381">Match Q with K, then mix V.</text><text x="237" y="408" class="architecture-causal">Current and earlier tokens only</text></g>
<path class="architecture-arrow" d="M 408 322 H 429"/>
<circle class="architecture-add" cx="450" cy="322" r="17"/><text class="architecture-plus" x="450" y="330">+</text>
<path class="architecture-residual" d="M 40 322 V 221 H 450 V 302"/>
<path class="architecture-arrow" d="M 470 322 H 553"/>
<g class="architecture-node architecture-operation"><rect x="560" y="238" width="280" height="185" rx="8"/><text x="700" y="267" class="architecture-heading">Feed forward</text><text x="700" y="309">Learned matrix multiplications</text><text x="700" y="339">with non-linear transformations,</text><text x="700" y="369">applied to each token</text></g>
<path class="architecture-arrow" d="M 843 322 H 859"/>
<circle class="architecture-add" cx="880" cy="322" r="17"/><text class="architecture-plus" x="880" y="330">+</text>
<path class="architecture-residual" d="M 510 322 V 221 H 880 V 302"/>
<path class="architecture-arrow" d="M 900 322 H 923"/>
<text class="architecture-purpose" x="237" y="455">Mix information between tokens</text><text class="architecture-purpose" x="700" y="455">Transform each token’s features</text>
<path class="architecture-feedback" d="M 967 348 H 950 V 510 H 1 V 130 H 417 V 101"/>
<text class="architecture-feedback-label" x="465" y="540">Append the selected token ID → predict the next token. Repeat until a stop token or limit.</text>
</svg><p class="architecture-scope">Simplified text-generation path through a modern decoder.</p>`,"Follow the top row: text becomes token IDs, then vectors. Repeated decoder blocks update those vectors. The vocabulary projection assigns scores to possible next tokens. Softmax turns scores into probabilities; sampling selects a token.\n\nInside a block, attention mixes information between tokens. Queries describe what to look for, keys provide matching information, and values carry the content to combine. Causal attention sees the current and earlier positions. Feed forward transforms each token’s features through learned matrix operations and nonlinear functions. The red paths add each update back to the original vector.\n\nFinally, the selected token goes back in. That loop generates the next token.",['decoder','illustrated','explainer']);
add('contract','Behind the JSON: prefill and decode',120,'HOW A CONVENTIONAL LLM GENERATES',`<div class="computation-columns"><div class="prefill-panel"><div class="phase-heading"><h3>1 / Prefill</h3><span>~2,000 tokens/s*</span></div><p class="prefill-summary">The whole prompt goes in <strong>at once.</strong></p><div class="prompt-bundle"><span>Instructions</span><span>Transaction</span><span>Document</span></div><svg class="prefill-graph prefill-matrices" viewBox="0 0 550 340" role="img" aria-label="Prefill combines instructions, transaction and document into a matrix of prompt token vectors. Model weight matrices multiply the entire prompt matrix, processing all token positions together. The full-prompt pass produces the first output token."><title>Prefill: matrix times matrix, all prompt vectors together</title><g class="prefill-stage" data-active="true"><text x="353" y="55" text-anchor="middle" class="matrix-label">All prompt vectors</text><rect x="257" y="83" width="23" height="23" rx="3"/><rect x="285" y="83" width="23" height="23" rx="3"/><rect x="313" y="83" width="23" height="23" rx="3"/><rect x="341" y="83" width="23" height="23" rx="3"/><rect x="369" y="83" width="23" height="23" rx="3"/><rect x="397" y="83" width="23" height="23" rx="3"/><rect x="425" y="83" width="23" height="23" rx="3"/><rect x="257" y="111" width="23" height="23" rx="3"/><rect x="285" y="111" width="23" height="23" rx="3"/><rect x="313" y="111" width="23" height="23" rx="3"/><rect x="341" y="111" width="23" height="23" rx="3"/><rect x="369" y="111" width="23" height="23" rx="3"/><rect x="397" y="111" width="23" height="23" rx="3"/><rect x="425" y="111" width="23" height="23" rx="3"/><rect x="257" y="139" width="23" height="23" rx="3"/><rect x="285" y="139" width="23" height="23" rx="3"/><rect x="313" y="139" width="23" height="23" rx="3"/><rect x="341" y="139" width="23" height="23" rx="3"/><rect x="369" y="139" width="23" height="23" rx="3"/><rect x="397" y="139" width="23" height="23" rx="3"/><rect x="425" y="139" width="23" height="23" rx="3"/><rect x="257" y="167" width="23" height="23" rx="3"/><rect x="285" y="167" width="23" height="23" rx="3"/><rect x="313" y="167" width="23" height="23" rx="3"/><rect x="341" y="167" width="23" height="23" rx="3"/><rect x="369" y="167" width="23" height="23" rx="3"/><rect x="397" y="167" width="23" height="23" rx="3"/><rect x="425" y="167" width="23" height="23" rx="3"/><text x="353" y="224" text-anchor="middle" class="matrix-kind">matrix</text><text x="353" y="251" text-anchor="middle" class="svg-caption">Each column is one token vector.</text></g><g class="prefill-stage" data-active="true"><text x="84" y="55" text-anchor="middle" class="matrix-label">Model weights</text><rect x="30" y="83" width="23" height="23" rx="3"/><rect x="58" y="83" width="23" height="23" rx="3"/><rect x="86" y="83" width="23" height="23" rx="3"/><rect x="114" y="83" width="23" height="23" rx="3"/><rect x="30" y="111" width="23" height="23" rx="3"/><rect x="58" y="111" width="23" height="23" rx="3"/><rect x="86" y="111" width="23" height="23" rx="3"/><rect x="114" y="111" width="23" height="23" rx="3"/><rect x="30" y="139" width="23" height="23" rx="3"/><rect x="58" y="139" width="23" height="23" rx="3"/><rect x="86" y="139" width="23" height="23" rx="3"/><rect x="114" y="139" width="23" height="23" rx="3"/><rect x="30" y="167" width="23" height="23" rx="3"/><rect x="58" y="167" width="23" height="23" rx="3"/><rect x="86" y="167" width="23" height="23" rx="3"/><rect x="114" y="167" width="23" height="23" rx="3"/><text x="84" y="224" text-anchor="middle" class="matrix-kind">matrix</text><text x="191" y="154" text-anchor="middle" class="matrix-multiply">×</text></g><path d="M 245 258 V 282 l -6 -7 m 6 7 l 6 -7"/><g class="prefill-stage" data-active="true"><rect class="prefill-result" x="15" y="290" width="520" height="43" rx="7"/><text x="275" y="318" text-anchor="middle">Full-prompt pass → first output token</text></g></svg><p class="computation-caption">Matrix × matrix operations across the model.</p></div><div class="decode-panel"><div class="phase-heading"><h3>2 / Decode</h3><span>~50 tokens/s*</span></div><p class="decode-summary">One token vector at a time, through the same model.</p><svg class="decode-vector" viewBox="0 0 550 108" role="img" aria-label="Model weights multiplied by one token vector, shown as a single row of cells"><title>Model weights times one token vector</title><text x="134" y="22" text-anchor="middle">Model weights</text><rect x="100" y="33" width="14" height="14" rx="2"/><rect x="118" y="33" width="14" height="14" rx="2"/><rect x="136" y="33" width="14" height="14" rx="2"/><rect x="154" y="33" width="14" height="14" rx="2"/><rect x="100" y="51" width="14" height="14" rx="2"/><rect x="118" y="51" width="14" height="14" rx="2"/><rect x="136" y="51" width="14" height="14" rx="2"/><rect x="154" y="51" width="14" height="14" rx="2"/><rect x="100" y="69" width="14" height="14" rx="2"/><rect x="118" y="69" width="14" height="14" rx="2"/><rect x="136" y="69" width="14" height="14" rx="2"/><rect x="154" y="69" width="14" height="14" rx="2"/><rect x="100" y="87" width="14" height="14" rx="2"/><rect x="118" y="87" width="14" height="14" rx="2"/><rect x="136" y="87" width="14" height="14" rx="2"/><rect x="154" y="87" width="14" height="14" rx="2"/><text x="255" y="78" text-anchor="middle" class="vector-multiply">×</text><text x="374" y="22" text-anchor="middle">One token vector</text><rect x="340" y="60" width="14" height="14" rx="2"/><rect x="358" y="60" width="14" height="14" rx="2"/><rect x="376" y="60" width="14" height="14" rx="2"/><rect x="394" y="60" width="14" height="14" rx="2"/></svg><svg class="decode-graph" viewBox="0 0 550 110" role="img" aria-label="Each previous output token passes through embeddings, full attention and feed-forward layers, and the vocabulary scoring layer to predict the next token. The output feeds back into the next step."><title>Decode: repeated forward passes, one new position at a time</title><g class="decode-step"><rect x="5" y="10" width="130" height="50" rx="6"/><text x="70" y="40" text-anchor="middle">Embed token</text></g><path d="M 138 35 H 164 l -6 -5 m 6 5 l -6 5"/><g class="decode-step"><rect x="170" y="10" width="210" height="50" rx="6"/><text x="275" y="31" text-anchor="middle">The same model</text><text x="275" y="51" text-anchor="middle" class="svg-caption">one token vector at a time</text></g><path d="M 385 35 H 410 l -6 -5 m 6 5 l -6 5"/><g class="decode-step"><rect x="415" y="10" width="130" height="50" rx="6"/><text x="480" y="40" text-anchor="middle">Vocab Score</text></g><path class="decode-loop" d="M 480 62 V 92 H 70 V 65 l -5 6 m 5 -6 l 5 6"/><text x="275" y="85" text-anchor="middle" class="svg-caption">next token → next forward pass</text></svg><div class="kv-cache"><div class="cache-label">KV CACHE <span class="cache-count">Prompt + ${illustrativeTokens.length-1} generated tokens</span></div><div class="cache-cells"><span class="prompt-cache">Prompt K, V</span>${illustrativeTokens.slice(1).map((_,i)=>`<span class="kv-entry" data-active="true" aria-label="Generated token ${i+1} cached"></span>`).join('')}</div></div><div class="decode-result"><div class="computation-tools"><div class="computation-status" role="status" aria-live="polite">Complete</div><button type="button" data-replay-computation>Replay ↻</button></div><pre aria-hidden="true"><code class="computation-output">${illustrativeTokens.join('')}</code></pre><span class="sr-only">Illustrative output: source of wealth business, confidence high.</span></div></div></div><p class="computation-footnote">*Indicative throughput, not a benchmark. Depends on hardware, context and batching. Animation slowed for teaching.</p>`,
"On the left, all prompt tokens are already known. The model processes their positions together, layer by layer. This creates large matrix-to-matrix operations that use accelerators efficiently. The final prompt position already supplies the scores for the first output token.\n\nOn the right, the next input depends on the previous output. For one sequence, decoding advances one token vector at a time. The KV cache keeps earlier attention information, so it need not all be recomputed, but each new token still passes through the model.\n\nThe throughput figures illustrate the contrast, not a universal ratio. Ask: which computation could disappear if we only wanted a category?",['inference','caching','config']);
add('read-decision','Do we need to spell it out?',30,'PAUSE / WE ONLY NEED A CATEGORY',`<div class="decision-pause"><p class="pause-context">Prefill has already processed the whole prompt.</p><p class="pause-question">We only need a category.<br><em>Could we read the decision directly?</em></p></div>`,"Pause here. The model has already processed all the evidence and produced a next-token distribution. For a simple bounded decision, that may be enough.\n\nThis does not mean every problem is solved during prefill: additional reasoning can improve difficult answers. Our narrower question is whether we need an entire generated sentence or JSON object when we only want one choice.",[]);
add('vocabulary','Vocab Score: One Number per Token',75,'FROM THE FINAL VECTOR TO THE NEXT TOKEN',`<p class="vocabulary-intro">The vocabulary is the model’s inventory of token IDs:<br>whole words, word parts, punctuation and special tokens.</p><p class="small">Qwen 3.8–27B: 248,320 vocabulary entries. Each raw score is a logit.</p><div class="vocabulary-scores" aria-label="Vocabulary tokens paired with their raw numeric scores">`+[['the','1.2'],['bank','−0.4'],['receives','2.1'],['dividend','3.8'],['ing','−1.6'],[',','0.7'],['{','2.5'],['&quot;','1.9'],['…','…']].map(([token,score])=>`<div><strong>${token}</strong><span>${score}</span></div>`).join('')+`</div>`,"The vocabulary is the inventory of token IDs the model can use. Tokens can represent whole words, parts of words, punctuation or special symbols. The Qwen configuration used here has 248,320 entries.\n\nAfter the full decoder stack, the final token’s hidden vector is projected into one number for every vocabulary entry. These numbers are logits: raw scores, not probabilities. Higher means more preferred at this position.\n\nThe scores shown here are just examples. The useful observation is that the model already scores possible answers before it samples anything.",['config']);
add('home-prompt','Let’s Build Jev at Home',60,'1 / GIVE EACH CHOICE A TOKEN',`<div class="home-prompt"><p>Mr Example receives USD 1M from Test Corp.<br>The dividend statement confirms the payment.</p><p>Classify the source of funds.</p><div class="home-options"><span><b>A</b> Business</span><span><b>B</b> Inheritance</span><span><b>C</b> Employment</span><span><b>D</b> Gift</span></div><p>What is the right choice: A, B, C or D?<br>Reply with only the letter.</p><div class="home-answer">Answer: <span aria-label="Stop here">▏</span></div></div><p class="small home-detail">Use labels that each map to one token at the answer position.</p>`,"Keep the transaction and statement, but change the requested answer. Map Business to A, Inheritance to B, Employment to C and Gift to D. Ask for only the letter, then stop at the answer position.\n\nChoose labels that are each one token in that exact context. Whitespace and tokenization matter. The meaning of A comes from the prompt; it is not permanently tied to Business.\n\nWe now have four relevant vocabulary entries. Instead of sampling one and continuing generation, we can read those entries directly.",['semif']);
add('readout','Read the Probabilities',90,'2 / KEEP THE FOUR CHOICES',`<p class="readout-caption">After softmax over the full vocabulary:</p><div class="vocabulary-scores readout-vocabulary" aria-label="Token probabilities after softmax. Rest combines all remaining tokens.">`+[['the','0.10'],['{','0.20'],['&quot;','0.15'],['A','0.34'],['B','0.02'],['C','0.02'],['D','0.02'],['rest','0.15']].map(([token,p])=>`<div class="${['A','B','C','D'].includes(token)?'choice-token':''}"><strong>${token}</strong><span>${p}</span></div>`).join('')+`</div><p class="readout-caption">Keep A, B, C and D. Divide each by their total.</p><div class="choice-normalization">${katex.renderToString(String.raw`q_i = \frac{p_i}{p_A+p_B+p_C+p_D}`, {displayMode:true,throwOnError:true})}${katex.renderToString(String.raw`q_A = \frac{0.34}{0.40} = 85\%`, {displayMode:true,throwOnError:true})}</div><div class="choice-constraints">${katex.renderToString(String.raw`0 \le q_i \le 1 \qquad \sum_{i \in \{A,B,C,D\}} q_i = 1`, {displayMode:true,throwOnError:true})}</div><p class="takeaway">Business 85% · Inheritance 5% · Employment 5% · Gift 5%</p>`,"Point to A, B, C and D in red. Their probabilities under the full vocabulary add up to 0.40. Divide each by that total to get a distribution over our four choices.\n\nFor A, 0.34 divided by 0.40 gives 0.85. The other three become 0.05 each. Every result lies between zero and one, and the four sum to one. Applying softmax directly to only those four logits gives the same result.\n\nWe have removed sampling and the answer-generation loop. But normalization alone does not make these numbers reliable probabilities of correctness. We will address that shortly.",['semif']);
add('recap','Jev 101: Summary',60,'THE BIG IDEAS',`<div class="decision-recap"><article><h3>The machinery is already there</h3><p>An LLM already turns context into token scores.<em>A different readout turns it into a decision engine.</em></p></article><article><h3>Skip the expensive part</h3><p>Read the decision after one prompt pass.<em>Eliminate the answer-generation loop to save time and compute.</em></p></article><article><h3>Bring the world knowledge with you</h3><p>Pretraining supplies language, concepts and relationships.<em>That knowledge transfers to new examples.</em></p></article><article><h3>New decisions, no retraining</h3><p>Describe the question and choices in the prompt.<em>The same model can tackle a new classification task.</em></p></article></div>`,"Four ideas so far. The scoring machinery already exists in an LLM. Reading a decision directly removes the generated-answer loop. The pretrained model brings broad language and world knowledge. And the prompt can define new questions and categories without a separate training run for each task.\n\nThis is the basic idea, not a reconstruction of TypeSafe’s private implementation. It explains why the approach is attractive. The next questions are how far that knowledge transfers, how several questions can share work, and how to make the probabilities useful.",['semif','transfer']);
add('just-a-classifier','“Just a Classifier”?',75,'AN OLD TASK / A BROADER CAPABILITY',`<div class="classifier-comparison"><article><h3>Train a model for a task</h3><p>Collect labeled examples.<br>Learn the task’s categories.</p><svg class="classifier-visual" viewBox="0 0 550 180" role="img" aria-label="Labeled transaction examples train a neural network to predict business, employment or gift"><title>Learn a task from labeled examples</title><rect class="paper-back" x="8" y="36" width="140" height="112" rx="5"/><rect class="paper-back" x="15" y="29" width="140" height="112" rx="5"/><rect class="paper-front" x="22" y="22" width="140" height="112" rx="5"/><path class="document-line" d="M38 42H115M38 52H140"/><text x="38" y="77">Dividend</text><rect class="label-tag" x="36" y="91" width="108" height="27" rx="4"/><text class="label-text" x="90" y="110" text-anchor="middle">business</text><path class="visual-arrow" d="M170 80H205l-7-5m7 5l-7 5"/><g class="network-links"><path d="M220 37L275 55M220 37L275 111M220 79L275 55M220 79L275 111M220 121L275 55M220 121L275 111M275 55L330 37M275 55L330 79M275 55L330 121M275 111L330 37M275 111L330 79M275 111L330 121"/></g><g class="network-nodes"><circle cx="220" cy="37" r="8"/><circle cx="220" cy="79" r="8"/><circle cx="220" cy="121" r="8"/><circle cx="275" cy="55" r="10"/><circle cx="275" cy="111" r="10"/><circle cx="330" cy="37" r="8"/><circle cx="330" cy="79" r="8"/><circle cx="330" cy="121" r="8"/></g><path class="document-line" d="M340 37H365M340 79H365M340 121H365"/><text x="378" y="43">Business</text><text x="378" y="85">Employment</text><text x="378" y="127">Gift</text><text class="visual-caption" x="90" y="170" text-anchor="middle">Examples + labels</text><text class="visual-caption" x="275" y="170" text-anchor="middle">Train the weights</text></svg></article><article><h3>Describe a task to a model</h3><p>Start with broad language and world knowledge.<br>Supply the question and choices.</p><svg class="classifier-visual" viewBox="0 0 550 180" role="img" aria-label="A person describes a transaction and candidate categories to a pretrained model, which returns business with 85 percent probability"><title>Describe a task to a pretrained model</title><circle class="person" cx="25" cy="40" r="13"/><path class="person" d="M4 83v-10a21 21 0 0 1 42 0v10"/><path class="speech-bubble" d="M72 14H354a8 8 0 0 1 8 8V73a8 8 0 0 1-8 8H88L62 94V24a10 10 0 0 1 10-10Z"/><text x="80" y="42">Classify this transaction.</text><text class="prompt-choices" x="80" y="65">Business / employment / gift…</text><path class="visual-arrow" d="M374 48H410l-7-5m7 5l-7 5"/><g class="network-links"><path d="M430 29L465 48L430 67M430 29L430 67M465 48L500 29M465 48L500 67M500 29L500 67"/></g><g class="network-nodes"><circle cx="430" cy="29" r="7"/><circle cx="430" cy="67" r="7"/><circle cx="465" cy="48" r="10"/><circle cx="500" cy="29" r="7"/><circle cx="500" cy="67" r="7"/></g><path class="answer-bubble" d="M272 110H442l24-17v56a8 8 0 0 1-8 8H272a8 8 0 0 1-8-8v-31a8 8 0 0 1 8-8Z"/><text class="answer-text" x="365" y="141" text-anchor="middle">Business · 85%</text><text class="visual-caption" x="465" y="92" text-anchor="middle">Pretrained model</text><text class="visual-caption" x="95" y="170" text-anchor="middle">A new task in words</text></svg></article></div><p class="classifier-takeaway">Transfer what it knows to a task you just described.</p><blockquote class="classifier-quote">“Jev’s impressive breakthrough is that it generalizes so well”<cite>Sebastian Raschka · 20 September 2026</cite></blockquote>`,"Classification itself is old. The interesting change is what the model already knows before we describe the task.\n\nOn the left, the familiar workflow collects labeled examples and trains a task-specific model. On the right, a pretrained language model can use a task described in words, drawing on knowledge learned across many domains. That makes new questions much easier to try.\n\nEarlier classifiers could also use transfer learning. The point is the breadth and flexibility of this interface, not that transfer is new. Nor does it guarantee performance in an unseen domain. That still needs evaluation.",['raschka','transfer']);
add('question-branches','Reuse the Work. Isolate the Questions.',105,'EXTENDING OUR LLM AT HOME / SHARED PREFIX',`<p class="branch-reason">Put the transaction and supporting documents before the questions.<br><em>Causal attention cannot look ahead: later questions cannot change its cached vectors.</em></p><svg class="question-branches" viewBox="0 0 1150 300" role="img" aria-label="Prefill the dividend transaction and statement once, then reuse the saved keys and values in three isolated branches. Source of funds returns Business at 85 percent, evidence support returns a score of 2.9 out of 3, and client is seller returns a yes probability of 0.02. Attention masks prevent branches from reading one another."><defs><marker id="branch-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z"/></marker></defs><rect x="10" y="80" width="320" height="140" rx="8"/><text x="170" y="116">Transaction + documents</text><text x="170" y="153" class="branch-small">USD 1M dividend from Test Corp</text><text x="170" y="191" class="branch-cache">Prefill once → saved K, V</text><path class="branch-link" d="M330 150H375V45H420"/><path class="branch-link" d="M375 150H420"/><path class="branch-link" d="M375 150V255H420"/>`+[['Source of funds?','Business · 85%',10],['How strong is the support?','Score: 2.9 / 3',115],['Is the client the seller?','P(yes): 0.02',220]].map(([label,answer,y])=>`<rect x="425" y="${y}" width="390" height="70" rx="8"/><text x="620" y="${y+30}">${label}</text><text x="620" y="${y+56}" class="branch-small">Attend to state + own branch only</text><path class="branch-link" d="M815 ${y+35}H875"/><rect x="880" y="${y}" width="250" height="70" rx="8"/><text x="1005" y="${y+43}">${answer}</text>`).join('')+`</svg><div class="branch-explanation"><p><strong>Isolation:</strong> the attention mask hides other branches.</p><p><strong>Efficiency:</strong> reuse the state cache; batch the question branches together.</p></div>`,"Use the same transaction for three questions: source of funds, strength of evidence, and whether the client is the seller.\n\nThe long state comes first. In a causal model, later questions cannot change the earlier state representations. We can compute the state once and reuse its cached keys and values. Each question branch can attend to that state and its own tokens, while an attention mask hides the other branches.\n\nThis gives shared work without one answer influencing another. The diagram explains an implementable branching design; it does not reveal TypeSafe’s unpublished internals. The questions must be answerable from the shared evidence independently.",['caching','semif']);
add('speculative-questions','Another Question Is Only Another Branch.',90,'WHY TYPESAFE RECOMMENDS SPECULATIVE QUESTIONS',`<p class="speculation-lead">10,000 tokens of transaction documents. Three 100-token questions.</p><div class="branch-accounting"><article><h3>Three separate requests</h3><div class="token-work">`+Array.from({length:3},()=>`<div><span>Read 10,000</span><b>+ 100</b></div>`).join('')+`</div><p>3 × (10,000 + 100)</p><strong>30,300 input tokens</strong></article><article><h3>One request, three branches</h3><div class="token-work shared-token-work"><span>Read 10,000 once</span><div><b>+ 100</b><b>+ 100</b><b>+ 100</b></div></div><p>10,000 + 3 × 100</p><strong>10,300 input tokens</strong></article></div><div class="speculative-why"><p><strong>Ask source of funds and “Is the client the seller?” together.</strong><br>The seller question can be answered directly from the documents.</p><p><em>If the transaction is employment income, discard the seller answer.</em><br>Asking upfront saves another call when the transaction is a sale.</p></div>`,"Walk through the token arithmetic. Three separate requests repeat the ten-thousand-token state three times. One request with three questions reads it once. That is 30,300 versus 10,300 input tokens in this simplified example.\n\nThis is why TypeSafe recommends asking even some speculative questions. We can ask whether the client is the seller at the same time as asking the source of funds. If the transaction is employment income, code discards the irrelevant seller answer.\n\nWe save a second round trip when that answer is needed. This works when the question can be answered from the documents, without waiting for another answer.",['parallel','fanout']);

sources.loraPaper = ['Hu et al. · LoRA, 2021', 'https://arxiv.org/abs/2106.09685'];
sources.promptBias = ['Zhao et al. · Calibrate Before Use, 2021', 'https://arxiv.org/abs/2102.09690'];
sources.semifCalibration = ['SemIf · calibration experiment', 'https://github.com/TheoLeeCJ/SemIf-OpenJev/blob/23cf1f39fc9534fe81437200959b6dfc7106e45a/docs/CALIBRATION.md'];

add('raw-probabilities','Adds Up to 1. Does It Deserve 97%?',60,'BEYOND JEV 101 / FROM TOKEN SCORES TO RELIABLE DECISIONS',`<p class="tech-lead">Reading label-token probabilities is an old idea.<br>A preference for the next token is not yet a reliable estimate of correctness.</p><div class="probability-question"><article><h3>Our transaction → four options</h3>${bars(['Business','Inheritance','Employment','Gift'],[.97,.01,.01,.01])}</article><article class="calibration-question"><strong>97%</strong><p>Across 100 comparable predictions<br>at 97%, are about 97 correct?</p><p class="tech-emphasis">That is the calibration question.</p></article></div><p class="tech-bottom">Raw readouts can be too sharp, or favor particular labels and positions.<br>Test the probabilities against outcomes—not just whether they sum to 1.</p>`,"Our homemade decision model returns 97% for Business. The numbers sum to one, but does 97% mean what we want it to mean?\n\nAsk the room: would you act on an 80% prediction? The answer depends on the consequence of an error and whether similar predictions really succeed about eight times in ten.\n\nLanguage models can prefer particular labels, answer positions or familiar phrasing. Their next-token probabilities can also be too concentrated. Calibration compares predicted probabilities with observed outcomes. Accuracy asks whether the winner is right; calibration asks whether the assigned uncertainty is meaningful.",['promptBias','calibration']);

add('bias-temperature','Two Knobs: Bias and Temperature',105,'1 / ADJUST THE READOUT',`<div class="calibration-formula">${katex.renderToString(String.raw`p_i=\frac{\exp((z_i+b_i)/T)}{\sum_j\exp((z_j+b_j)/T)}`,{displayMode:true})}</div><div class="tech-columns"><article><h3>Bias · move individual scores</h3><p>A separate offset for each option.<br>Correct a persistent preference for A, for example.</p><div class="bias-example"><span>A: 4</span><b>+ (−1)</b><span>3</span></div><p class="small">Can change which option wins.<br>The same offset for every option cancels out.</p></article><article><h3>Temperature · change the spread</h3><p>Divide every adjusted score by T.<br>T &gt; 1 softens; 0 &lt; T &lt; 1 sharpens.</p><div class="temperature-example"><span>Same four option scores</span><div><b>T = 1</b><span>94% · 2% · 2% · 2%</span></div><div><b>T = 2</b><span>70% · 10% · 10% · 10%</span></div></div><p class="small">Keeps the winning option unchanged.</p></article></div><svg class="temperature-distribution" viewBox="0 0 1150 180" role="img" aria-label="The same token scores at two temperatures. T equals 1 has a narrow high peak. T equals 2, in red, spreads probability over more tokens with a lower peak."><title>Higher temperature spreads probability over more tokens</title><path class="temperature-axis" d="M220 142H920"/><text x="160" y="60">Probability</text><text x="570" y="174" text-anchor="middle">Possible tokens</text><path class="temperature-cold" d="M240.0,142.0 L251.0,142.0 L262.0,142.0 L273.0,142.0 L284.0,142.0 L295.0,142.0 L306.0,142.0 L317.0,142.0 L328.0,142.0 L339.0,142.0 L350.0,142.0 L361.0,142.0 L372.0,142.0 L383.0,142.0 L394.0,142.0 L405.0,141.9 L416.0,141.7 L427.0,141.4 L438.0,140.7 L449.0,139.3 L460.0,136.7 L471.0,132.5 L482.0,125.8 L493.0,116.1 L504.0,103.1 L515.0,87.2 L526.0,69.4 L537.0,51.7 L548.0,36.4 L559.0,26.0 L570.0,22.3 L581.0,26.0 L592.0,36.4 L603.0,51.7 L614.0,69.4 L625.0,87.2 L636.0,103.1 L647.0,116.1 L658.0,125.8 L669.0,132.5 L680.0,136.7 L691.0,139.3 L702.0,140.7 L713.0,141.4 L724.0,141.7 L735.0,141.9 L746.0,142.0 L757.0,142.0 L768.0,142.0 L779.0,142.0 L790.0,142.0 L801.0,142.0 L812.0,142.0 L823.0,142.0 L834.0,142.0 L845.0,142.0 L856.0,142.0 L867.0,142.0 L878.0,142.0 L889.0,142.0 L900.0,142.0"/><path class="temperature-warm" d="M240.0,142.0 L251.0,142.0 L262.0,142.0 L273.0,142.0 L284.0,142.0 L295.0,142.0 L306.0,142.0 L317.0,142.0 L328.0,142.0 L339.0,141.9 L350.0,141.8 L361.0,141.7 L372.0,141.5 L383.0,141.1 L394.0,140.4 L405.0,139.5 L416.0,138.0 L427.0,136.0 L438.0,133.1 L449.0,129.2 L460.0,124.3 L471.0,118.1 L482.0,110.9 L493.0,102.6 L504.0,93.8 L515.0,84.7 L526.0,76.1 L537.0,68.5 L548.0,62.5 L559.0,58.7 L570.0,57.4 L581.0,58.7 L592.0,62.5 L603.0,68.5 L614.0,76.1 L625.0,84.7 L636.0,93.8 L647.0,102.6 L658.0,110.9 L669.0,118.1 L680.0,124.3 L691.0,129.2 L702.0,133.1 L713.0,136.0 L724.0,138.0 L735.0,139.5 L746.0,140.4 L757.0,141.1 L768.0,141.5 L779.0,141.7 L790.0,141.8 L801.0,141.9 L812.0,142.0 L823.0,142.0 L834.0,142.0 L845.0,142.0 L856.0,142.0 L867.0,142.0 L878.0,142.0 L889.0,142.0 L900.0,142.0"/><path class="temperature-cold" d="M950 62h40"/><text x="1005" y="69">T = 1</text><path class="temperature-warm" d="M950 100h40"/><text class="temperature-red" x="1005" y="107">T = 2</text></svg>`,"There are two simple adjustments. Bias adds a separate offset to each score. It can correct a persistent preference for a label and can change which option wins. Adding the same offset everywhere changes nothing after softmax.\n\nTemperature divides all adjusted scores by a positive number. A temperature above one spreads probability more evenly; below one makes it sharper. Point to the grey and red curves. The winner stays the same, but the probabilities change.\n\nFit these values on held-out examples with known outcomes. Smoothing is not automatically improvement: it helps only when the original distribution is too confident in the relevant setting.",['calibration','promptBias']);

add('calibration-in-code','Open Implementations',90,'INSPECTED IMPLEMENTATIONS / SOURCE SNAPSHOT · 23 OCT 2026',`<div class="tech-columns implementation-comparison"><article><h3>SemIf · temperature alone</h3><p>Keep the LLM frozen.<br>Fit T by minimizing label log loss.</p><div class="calibration-metric"><span>WANLI · 256 examples</span><strong>T ≈ 2.50</strong></div><div class="metric-change"><span>0.208</span><b>→</b><span>0.069</span></div><p class="small">Expected calibration error, raw → out-of-fold.<br>Five folds; accuracy stays 63.7%.<br>The release temperature is fitted on all 256 rows.</p></article><article><h3>AutoTrust JEV-27B · bias + T</h3><p>Add the trained decision head’s bias.<br>Apply a fitted temperature for each question type.</p><div class="kind-temperatures"><div><span>Noul</span><b>1.014</b></div><div><span>Choice</span><b>1.016</b></div><div><span>Score</span><b>1.004</b></div></div><p class="small">10,954 temperature-fit rows.<br>Bias is learned with the head; temperature is fitted afterward.</p></article></div><p class="tech-bottom">AutoTrust’s temperatures barely move the distribution.<br>Its adapters and decision head have already learned from soft targets.</p>`,"Here are two concrete implementations. SemIf keeps the model frozen and fits temperature. In its small WANLI experiment, the out-of-fold calibration error falls while accuracy stays unchanged. That is exactly what temperature alone should be able to do: adjust certainty without changing the ranking.\n\nAutoTrust has a learned decision-head bias and a fitted temperature for each question type. Notice how close its temperatures are to one. Most of the adaptation has already happened during training of its adapters and decision head.\n\nThese are separate projects with different training and evaluation setups. Let’s open up AutoTrust’s architecture next.",['semifCalibration','code','temperatures']);

add('autotrust-architecture','Inside AutoTrust JEV-27B',105,'OPEN MODEL / THE DECISION PATH',`<svg class="autotrust-architecture" viewBox="0 0 1150 515" role="img" aria-labelledby="at-title at-desc"><title id="at-title">AutoTrust combines a frozen Qwen backbone with trainable adapters and a calibrated decision head</title><desc id="at-desc">Transaction, question and options enter Qwen3.8 27B. Rank16 LoRA updates attention and feed-forward projections inside the frozen decoder. Its final5120-feature vector feeds a trained projection plus learned bias producing24 slots: two Noul, six Score, sixteen Choice. For the four-option transaction question, activate Choice slots A through D, divide scores by the fitted Choice temperature, and softmax to obtain probabilities.</desc><defs><marker id="at-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z"/></marker></defs>
<rect class="at-input" x="5" y="151" width="175" height="150" rx="10"/><path class="at-document" d="M27 181H76M27 191H115M27 201H96"/><text x="27" y="231">Transaction</text><text class="at-small" x="27" y="258">+ question</text><text class="at-small" x="27" y="283">+ options A–D</text><path class="at-link" d="M185 226H230"/>
<rect class="at-base" x="235" y="40" width="380" height="365" rx="15"/><text class="at-title" x="265" y="83">Qwen3.8–27B</text><text class="at-small" x="265" y="113">Frozen text backbone · 64 layers</text><rect class="at-layer" x="265" y="159" width="180" height="42" rx="6"/><text class="at-small" x="355" y="186" text-anchor="middle">Attention</text><path class="at-update" d="M505 180H450"/><rect class="at-adapter" x="510" y="159" width="76" height="42" rx="6"/><text class="at-adapter-text" x="548" y="186" text-anchor="middle">LoRA</text><rect class="at-layer" x="265" y="218" width="180" height="42" rx="6"/><text class="at-small" x="355" y="245" text-anchor="middle">Feed forward</text><path class="at-update" d="M505 239H450"/><rect class="at-adapter" x="510" y="218" width="76" height="42" rx="6"/><text class="at-adapter-text" x="548" y="245" text-anchor="middle">LoRA</text><rect class="at-layer" x="265" y="277" width="180" height="42" rx="6"/><text class="at-small" x="355" y="304" text-anchor="middle">Attention</text><path class="at-update" d="M505 298H450"/><rect class="at-adapter" x="510" y="277" width="76" height="42" rx="6"/><text class="at-adapter-text" x="548" y="304" text-anchor="middle">LoRA</text><text class="at-small" x="265" y="362">Final vector: 5,120 features</text><text class="at-red at-small" x="265" y="389">Trainable updates · rank 16</text>
<path class="at-link" d="M620 226H650"/>
<rect class="at-head" x="655" y="40" width="485" height="275" rx="15"/><text class="at-title" x="680" y="82">Decision projection + bias</text><text class="at-small" x="680" y="111">24 learned output slots</text><text class="at-small" x="680" y="142">Noul · 2</text><rect class="at-slot" x="670" y="151" width="20" height="26" rx="3"/><rect class="at-slot" x="697" y="151" width="20" height="26" rx="3"/><text class="at-small" x="680" y="203">Score · 6</text><rect class="at-slot" x="670" y="212" width="20" height="26" rx="3"/><rect class="at-slot" x="697" y="212" width="20" height="26" rx="3"/><rect class="at-slot" x="724" y="212" width="20" height="26" rx="3"/><rect class="at-slot" x="751" y="212" width="20" height="26" rx="3"/><rect class="at-slot" x="778" y="212" width="20" height="26" rx="3"/><rect class="at-slot" x="805" y="212" width="20" height="26" rx="3"/><text class="at-small" x="680" y="264">Choice · 16</text><rect class="at-active" x="670" y="273" width="20" height="26" rx="3"/><rect class="at-active" x="697" y="273" width="20" height="26" rx="3"/><rect class="at-active" x="724" y="273" width="20" height="26" rx="3"/><rect class="at-active" x="751" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="778" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="805" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="832" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="859" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="886" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="913" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="940" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="967" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="994" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="1021" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="1048" y="273" width="20" height="26" rx="3"/><rect class="at-slot" x="1075" y="273" width="20" height="26" rx="3"/>
<path class="at-link" d="M790 320V355"/><text class="at-small" x="815" y="341">Keep A–D</text><rect class="at-calibration" x="655" y="360" width="270" height="120" rx="12"/><text x="680" y="397">÷ Temperature</text><text class="at-small" x="680" y="425">Choice: T ≈ 1.016</text><text class="at-red" x="680" y="459">Softmax</text><path class="at-link" d="M930 420H975"/>
<text class="at-small" x="988" y="352">Probabilities</text><text class="at-small" x="988" y="386">A</text><rect class="at-track" x="1010" y="370" width="125" height="18" rx="3"/><rect class="at-active" x="1010" y="370" width="87.5" height="18" rx="3"/><text class="at-small" x="988" y="415">B</text><rect class="at-track" x="1010" y="399" width="125" height="18" rx="3"/><rect class="at-active" x="1010" y="399" width="12.5" height="18" rx="3"/><text class="at-small" x="988" y="444">C</text><rect class="at-track" x="1010" y="428" width="125" height="18" rx="3"/><rect class="at-active" x="1010" y="428" width="18.75" height="18" rx="3"/><text class="at-small" x="988" y="473">D</text><rect class="at-track" x="1010" y="457" width="125" height="18" rx="3"/><rect class="at-active" x="1010" y="457" width="6.25" height="18" rx="3"/>
<rect class="at-layer" x="245" y="454" width="16" height="16" rx="3"/><text class="at-small" x="272" y="468">Frozen</text><rect class="at-adapter" x="380" y="454" width="16" height="16" rx="3"/><text class="at-small" x="407" y="468">Learned additions</text></svg>`,"Follow the decision path from left to right. The evidence, question and options enter a frozen Qwen3.8 27B backbone. Small LoRA updates are inserted inside attention and feed-forward projections.\n\nThe final hidden vector feeds a trained decision projection with a learned bias. It produces 24 slots: two for Noul, six for Score and sixteen for Choice. For our four-option example, we keep four Choice slots, apply the fitted temperature and normalize.\n\nAutoTrust is an independent open model, not TypeSafe Jev. It also retains a generation path. Here we are following its specialized decision path, whose published implementation we can inspect.",['card','adapter','slots','temperatures']);

add('decision-lora','LoRA: Low Rank Adapters',90,'2 / ADAPT THE COMPUTATION · AUTOTRUST JEV-27B',`<p class="tech-lead">Keep the original model weights frozen.<br>Train small updates that teach it how to make decisions.</p><svg class="lora-perspective" viewBox="0 0 1150 350" role="img" aria-labelledby="lora-perspective-title lora-perspective-desc"><title id="lora-perspective-title">Large frozen weight matrices and a small trainable adapter</title><desc id="lora-perspective-desc">Four large grey gridded squares in perspective represent the original model weights. A smaller red square represents the LoRA adapters collectively. AutoTrust has approximately108 million LoRA parameters, about0.4percent of its backbone. Adapters are applied inside attention and feed-forward projections.</desc><defs><pattern id="lora-weight-grid" width="21" height="21" patternUnits="userSpaceOnUse"><path d="M21 0H0V21" fill="none" stroke="#b9b9b1" stroke-width=".8"/></pattern><pattern id="lora-update-grid" width="16" height="16" patternUnits="userSpaceOnUse"><path d="M16 0H0V16" fill="none" stroke="#ff8585" stroke-width=".8"/></pattern></defs><g transform="translate(90 100) matrix(.8 -.3 0 1 0 0)"><rect class="lora-weight-edge" x="8" y="8" width="210" height="210" rx="3"/><rect class="lora-weight-face" width="210" height="210" rx="3"/><rect fill="url(#lora-weight-grid)" width="210" height="210"/></g><g transform="translate(198 92) matrix(.8 -.3 0 1 0 0)"><rect class="lora-weight-edge" x="8" y="8" width="210" height="210" rx="3"/><rect class="lora-weight-face" width="210" height="210" rx="3"/><rect fill="url(#lora-weight-grid)" width="210" height="210"/></g><g transform="translate(306 84) matrix(.8 -.3 0 1 0 0)"><rect class="lora-weight-edge" x="8" y="8" width="210" height="210" rx="3"/><rect class="lora-weight-face" width="210" height="210" rx="3"/><rect fill="url(#lora-weight-grid)" width="210" height="210"/></g><g transform="translate(414 76) matrix(.8 -.3 0 1 0 0)"><rect class="lora-weight-edge" x="8" y="8" width="210" height="210" rx="3"/><rect class="lora-weight-face" width="210" height="210" rx="3"/><rect fill="url(#lora-weight-grid)" width="210" height="210"/></g><text class="lora-plus" x="638" y="202">+</text><g transform="translate(715 150) matrix(.8 -.3 0 1 0 0)"><rect class="lora-update-edge" x="7" y="7" width="96" height="96" rx="3"/><rect class="lora-update-face" width="96" height="96" rx="3"/><rect fill="url(#lora-update-grid)" width="96" height="96"/></g><text class="lora-count" x="860" y="165">108M</text><text class="lora-count-label" x="860" y="200">LoRA parameters</text><text class="lora-share" x="860" y="235">≈ 0.4% of the backbone</text><text class="lora-weight-label" x="300" y="337" text-anchor="middle">Original weights · frozen</text><text class="lora-update-label" x="755" y="302" text-anchor="middle">Small learned updates</text></svg><div class="lora-explanation"><p><strong>“Low rank”:</strong> two small matrices represent each weight update.<br>AutoTrust uses rank 16, reducing how many parameters need training.</p><p>The updates sit inside attention and feed forward, adapting how the model reads the evidence.</p></div>`,"The grey squares represent the original weight matrices. They stay frozen. The red square represents small learned updates spread through the model, not a single layer attached at the end.\n\nLoRA represents each update using two smaller matrices. Their low rank limits the number of trainable parameters. AutoTrust uses rank 16 and about 108 million LoRA parameters, around 0.4% of the backbone size.\n\nThese updates change how the model processes the evidence while retaining its pretrained weights. This is more powerful than adjusting the final probabilities alone: we are adapting the internal representation that will drive the decision.",['loraPaper','adapter','card']);

add('decision-head','Give the Model a Decision Ending',90,'3 / TRAIN A SPECIALIZED OUTPUT · AUTOTRUST JEV-27B',`<p class="tech-lead">After the decoder stack, read the final position’s 5,120 features.<br>Train a small projection to decision slots instead of the whole vocabulary.</p><svg class="tech-diagram head-diagram" viewBox="0 0 1150 250" role="img" aria-label="Final hidden vector of 5120 features is multiplied by a trained 24 by 5120 weight matrix and a bias is added. The 24 output slots are two Noul, six Score, and sixteen Choice. Select active slots, divide by temperature, and softmax."><rect class="frozen" x="5" y="50" width="190" height="130" rx="8"/><text x="100" y="99">Final vector</text><text class="diagram-small" x="100" y="137">5,120 features</text><path d="M200 115H250l-8-6m8 6l-8 6"/><rect class="trained" x="255" y="50" width="265" height="130" rx="8"/><text x="387" y="99">Decision projection</text><text class="diagram-small" x="387" y="137">24 × 5,120 weights + bias</text><path d="M525 115H575l-8-6m8 6l-8 6"/><rect class="trained" x="580" y="10" width="560" height="65" rx="6"/><text x="860" y="49">Noul · false / true · 2 slots</text><rect class="trained" x="580" y="85" width="560" height="65" rx="6"/><text x="860" y="124">Score · 0 / 1 / 2 / 3 / 4 / 5 · 6 slots</text><rect class="trained" x="580" y="160" width="560" height="65" rx="6"/><text x="860" y="199">Choice · A / B / C / … / P · 16 slots</text></svg><div class="slot-mapping"><b>For our four options</b><span>A → Business</span><span>B → Inheritance</span><span>C → Employment</span><span>D → Gift</span></div><p class="tech-bottom">Keep the active slots → divide by temperature → softmax.<br>The prompt defines what each slot means. The head learns how to score it.</p>`,"The final token position has 5,120 features. Instead of projecting those features onto the entire vocabulary, AutoTrust trains a small projection onto 24 decision slots, plus a bias.\n\nThe slots are organized by question type. A four-way Choice uses four of the sixteen available Choice slots. The prompt explains what A, B, C and D mean for this request. Tomorrow, those same slots can represent different categories.\n\nThis separates a stable output shape from runtime-defined meanings. The head is small, but it must be trained to interpret the final representation correctly. Temperature then adjusts the active slot distribution.",['slots','card','code']);

sources.rlcdPrimer = ['TypeSafe · AI primer', 'https://docs.typesafe.ai/introduction/machine-learning-primer'];
add('rlcd-training','Reinforcement Learning for Calibrated Decisions',90,'TYPESAFE’S TRAINING GOAL / RLCD',`<p class="rlcd-lead">Learn which decisions to make <em>and how much probability they deserve.</em></p><svg class="rlcd-concept" viewBox="0 0 1150 240" role="img" aria-label="Calibration goal: across comparable predictions assigned80percent, roughly16 of20 outcomes should occur. Probabilities should match observed frequencies."><text class="rlcd-probability" x="90" y="128">80%</text><text class="rlcd-caption" x="95" y="173">Assigned probability</text><path class="rlcd-arrow" d="M340 110H580l-10-7m10 7l-10 7"/><text class="rlcd-caption" x="455" y="161" text-anchor="middle">Across many decisions</text><circle class="rlcd-correct" cx="675" cy="85" r="12"/><circle class="rlcd-correct" cx="715" cy="85" r="12"/><circle class="rlcd-correct" cx="755" cy="85" r="12"/><circle class="rlcd-correct" cx="795" cy="85" r="12"/><circle class="rlcd-correct" cx="835" cy="85" r="12"/><circle class="rlcd-correct" cx="875" cy="85" r="12"/><circle class="rlcd-correct" cx="915" cy="85" r="12"/><circle class="rlcd-correct" cx="955" cy="85" r="12"/><circle class="rlcd-correct" cx="995" cy="85" r="12"/><circle class="rlcd-correct" cx="1035" cy="85" r="12"/><circle class="rlcd-correct" cx="675" cy="135" r="12"/><circle class="rlcd-correct" cx="715" cy="135" r="12"/><circle class="rlcd-correct" cx="755" cy="135" r="12"/><circle class="rlcd-correct" cx="795" cy="135" r="12"/><circle class="rlcd-correct" cx="835" cy="135" r="12"/><circle class="rlcd-correct" cx="875" cy="135" r="12"/><circle class="rlcd-miss" cx="915" cy="135" r="12"/><circle class="rlcd-miss" cx="955" cy="135" r="12"/><circle class="rlcd-miss" cx="995" cy="135" r="12"/><circle class="rlcd-miss" cx="1035" cy="135" r="12"/><text class="rlcd-caption" x="855" y="192" text-anchor="middle">About 16 in 20 outcomes occur</text></svg><div class="rlcd-facts"><article><h3>The stated objective</h3><p>Train decisions with calibrated uncertainty.<br>Rewarding a good answer alone does not establish that its probability is reliable.</p></article><article><h3>What remains private</h3><p>The reward formula, training recipe,<br>corpus contents and number of examples.</p></article></div><p class="rlcd-transition">Next: AutoTrust’s published approach learns from full teacher distributions.</p>`,"TypeSafe calls its approach reinforcement learning for calibrated decisions. The stated goal is to learn useful decisions together with probabilities that reflect their uncertainty.\n\nThe picture illustrates the target: across many comparable predictions assigned 80%, about sixteen out of twenty should occur. It is a property of a collection of predictions, not a guarantee for an individual case.\n\nTypeSafe has not published the reward formula, detailed training recipe or corpus size. We should not fill in those gaps. Standard language-model training already learns probabilities; the distinction here is a training objective directed at calibrated decisions. AutoTrust offers a different, published recipe.",['rlcdPrimer','rlcd'],{titleHtml:'Reinforcement Learning<br>for <span class="rlcd-highlight">Calibrated</span> Decisions'});

add('decision-training','Train the Distribution, Not Just the Winner',90,'PUTTING IT TOGETHER / AUTOTRUST’S DISTILLATION RECIPE',`<div class="tech-columns training-distributions"><article><h3>Teacher target</h3>${bars(['Business','Inheritance','Employment','Gift'],[.7,.1,.15,.05])}</article><article><h3>Student prediction</h3>${bars(['Business','Inheritance','Employment','Gift'],[.9,.03,.05,.02])}</article></div><p class="distribution-lesson">Both pick Business. Training still penalizes the student’s overconfidence.</p><div class="training-steps"><article><b>1 · Learn</b><p>Train LoRA + slot weights + bias to match the teacher’s full distribution.</p></article><article><b>2 · Calibrate</b><p>Freeze the trained model.<br>Fit a temperature per question type on held-out rows.</p></article><article><b>3 · Evaluate</b><p>Check decision accuracy and calibration against independent outcome labels.</p></article></div><p class="small training-objective">AutoTrust: KL divergence over active slots; an extra ordered-score loss for Score.<br>Teacher-distribution distillation is its published recipe. TypeSafe describes its own training as RLCD.</p>`,"Both distributions choose Business, but they disagree about uncertainty. The teacher assigns 70%; the student assigns 90%. Training only the winning category would miss that difference.\n\nAutoTrust trains its LoRA updates, slot weights and bias to match the full teacher distribution. It uses a distribution-matching loss, with an additional ordered-score loss for Score questions. After training, it fits temperatures on held-out rows.\n\nFinally, evaluate against independent outcome labels. Matching a teacher is not proof of correctness or calibration: the student can inherit the teacher’s mistakes. This is distillation from Jev probabilities, not TypeSafe’s private RLCD recipe.",['card','temperatures','rlcd']);

add('calibration-recap','Keep the Knowledge. Learn the Odds.',45,'CALIBRATION / AUTOTRUST RECAP',`<div class="recap-art"><img src="${recapImage}" alt="A large pale model sphere surrounded by three small red learned components"/><div class="recap-art-base">Qwen3.8<span>27B · frozen</span></div><div class="recap-art-lora">LoRA<span>Small weight updates</span></div><div class="recap-art-head">Decision head<span>Slots + learned bias</span></div><div class="recap-art-temperature">Temperature<span>Fit after training</span></div></div><p class="calibration-recap-link">Small additions, trained on decisions and Jev’s probabilities.</p>`,"Pause and simplify. The large sphere is the pretrained Qwen model. We keep that foundation and train relatively small components around it: internal LoRA updates, a decision head with bias, and temperature adjustments.\n\nThe result is a model adapted to decisions and teacher distributions. We have moved from reading arbitrary label-token scores to a purpose-trained readout. Now we need to see how it performs.",['card','temperatures']);

